const batchId = String($input.first().json.batch_id ?? '').trim().toLowerCase();
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
if (!UUID.test(batchId)) {
  throw new Error('batch_id must be a UUID');
}
return [{ json: { batch_id: batchId } }];

const raw = $input.first().json.config;
const batchId = $('Check · Read batch_id').first().json.batch_id;
const EMAIL = /^[^@\s,;<>]+@[^@\s,;<>]+$/;

const problems = [];
if (typeof raw.dry_run !== 'boolean') {
  problems.push('dry_run must be true or false');
}
const aliases = Array.isArray(raw.test_inbox_aliases) ? raw.test_inbox_aliases : [];
if (aliases.length === 0 || !aliases.every((a) => typeof a === 'string' && EMAIL.test(a.trim()))) {
  problems.push('test_inbox_aliases must be a non-empty list of email addresses');
}
const maxEmails = raw.max_emails_per_run;
if (!Number.isInteger(maxEmails) || maxEmails < 1) {
  problems.push('max_emails_per_run must be a whole number of at least 1');
}
if (problems.length > 0) {
  throw new Error(`app_config invalid: ${problems.join('; ')}`);
}

return [{
  json: {
    batch_id: batchId,
    dry_run: raw.dry_run,
    aliases: [...new Set(aliases.map((a) => a.trim().toLowerCase()))],
    max_emails: maxEmails,
  },
}];

const config = $('Config · Validate settings').first().json;
const selected = $input.first().json;

const MAX_REASON_CHARS = 240;
const DISCLAIMER =
  'These options are indicative only. They are matched against the eligibility criteria ' +
  'published on each lender\'s website, not against a credit check. The lender decides ' +
  'eligibility, rate and amount after its own verification. This is not an offer of credit.';
const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ESCAPES[c]);
const safeUrl = (url) => (/^https?:\/\//i.test(String(url ?? '')) ? String(url) : null);
const shorten = (text) => {
  const clean = String(text ?? '').replace(/\s+/g, ' ').trim();
  return clean.length > MAX_REASON_CHARS ? `${clean.slice(0, MAX_REASON_CHARS - 1)}…` : clean;
};

const describeRate = (offer) => {
  const low = offer.rate_min === null ? null : Number(offer.rate_min);
  const high = offer.rate_max === null ? null : Number(offer.rate_max);
  if (low === null && high === null) return 'Interest rate not published on the lender page';
  if (high === null) return `Interest rate from ${low}% p.a.`;
  if (low === null) return `Interest rate up to ${high}% p.a.`;
  if (low === high) return `Interest rate ${low}% p.a.`;
  return `Interest rate ${low}% to ${high}% p.a.`;
};

const aliasFor = (userId) => {
  const bucket = parseInt(userId.replace(/-/g, '').slice(0, 8), 16);
  return config.aliases[bucket % config.aliases.length];
};

const offerText = (offer, index) => {
  const link = safeUrl(offer.source_url);
  const lines = [
    `${index + 1}. ${offer.lender} - ${offer.product_name}`,
    `   ${describeRate(offer)}`,
    `   Why: ${shorten(offer.reason)}`,
  ];
  if (link) lines.push(`   Details: ${link}`);
  return lines.join('\n');
};

const offerHtml = (offer) => {
  const link = safeUrl(offer.source_url);
  const details = link ? ` <a href="${escapeHtml(link)}">Lender page</a>` : '';
  return (
    '<tr><td style="padding:10px 0;border-bottom:1px solid #e5e7eb">' +
    `<strong>${escapeHtml(offer.lender)} - ${escapeHtml(offer.product_name)}</strong><br>` +
    `${escapeHtml(describeRate(offer))}<br>` +
    `<span style="color:#4b5563">Why: ${escapeHtml(shorten(offer.reason))}</span>${details}` +
    '</td></tr>'
  );
};

const buildEmail = (recipient) => {
  const offers = recipient.offers;
  const count = offers.length;
  const noun = count === 1 ? 'option' : 'options';
  const subject = `[TEST] ${count} personal loan ${noun} you may qualify for`;
  const intendedFor = `${recipient.name} <${recipient.original_email}>`;
  const text = [
    `Hello ${recipient.name},`,
    '',
    `Based on the details you shared, you may qualify for ${count} personal loan ${noun}:`,
    '',
    offers.map(offerText).join('\n\n'),
    '',
    DISCLAIMER,
    '',
    `Intended for: ${intendedFor}`,
    'This is a test delivery: every message is redirected to a test inbox.',
  ].join('\n');
  const html =
    '<!doctype html><html><body style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#111827">' +
    `<p>Hello ${escapeHtml(recipient.name)},</p>` +
    `<p>Based on the details you shared, you may qualify for ${count} personal loan ${noun}:</p>` +
    `<table style="width:100%;border-collapse:collapse">${offers.map(offerHtml).join('')}</table>` +
    `<p style="color:#4b5563;font-size:13px">${escapeHtml(DISCLAIMER)}</p>` +
    `<p style="color:#6b7280;font-size:12px">Intended for: ${escapeHtml(intendedFor)}<br>` +
    'This is a test delivery: every message is redirected to a test inbox.</p>' +
    '</body></html>';
  return {
    user_id: recipient.user_id,
    original_email: recipient.original_email,
    to: aliasFor(recipient.user_id),
    subject,
    html,
    text,
    offer_count: count,
  };
};

return [{
  json: {
    batch_id: selected.batch_id,
    dry_run: config.dry_run,
    users_waiting: selected.users_waiting,
    users_selected: selected.users_selected,
    emails: selected.recipients.map(buildEmail),
  },
}];

const config = $('Config · Validate settings').first().json;
const run = $input.first().json;
const allowed = new Set(config.aliases);
const COPY_FIELDS = ['cc', 'bcc', 'replyTo'];
const MAX_REPORTED = 5;

const problems = [];
if (allowed.size === 0) {
  problems.push('the test inbox list is empty');
}
if (run.emails.length > config.max_emails) {
  problems.push(`${run.emails.length} emails exceed the cap of ${config.max_emails}`);
}
for (const email of run.emails) {
  if (typeof email.to !== 'string' || !allowed.has(email.to)) {
    problems.push(`user ${email.user_id} would go to ${email.to}, which is not a test inbox`);
  }
  if (COPY_FIELDS.some((field) => field in email)) {
    problems.push(`user ${email.user_id} has a copy or reply-to recipient`);
  }
}
if (problems.length > 0) {
  const shown = problems.slice(0, MAX_REPORTED).join('; ');
  throw new Error(`recipient guard blocked the run (${problems.length} problems): ${shown}`);
}

return [{
  json: { ...run, guard: { checked: run.emails.length, test_inboxes: allowed.size } },
}];
